const stats = $json;
const today = new Date().toLocaleDateString('ko-KR', {year: 'numeric', month: 'long', day: 'numeric'});

const statsText = JSON.stringify(stats, null, 2).slice(0, 800);

return [{
  json: {
    stats: stats,
    reportDate: today,
    geminiRequest: {
      model: 'gemini-2.0-flash',
      max_tokens: 500,
      messages: [
        {
          role: 'system',
          content: 'POCAT 카드 거래 플랫폼 비즈니스 인사이트 리포트 생성 AI입니다. 데이터를 분석하고 한국어로 경영진이 읽기 좋게 5~7줄로 작성하세요.'
        },
        {
          role: 'user',
          content: today + ' POCAT 일일 통계 데이터:\n' + statsText + '\n\n다음 항목을 포함해 분석하세요:\n1. 오늘의 주요 지표 요약\n2. 전날 대비 주목할 변화\n3. 이상 거래 또는 시스템 이슈\n4. 비즈니스 기회 또는 위험 요소\n5. 내일 주목해야 할 사항'
        }
      ]
    }
  }
}];

const geminiResp = $json;
const report = (geminiResp.choices && geminiResp.choices[0] && geminiResp.choices[0].message && geminiResp.choices[0].message.content) || '리포트 생성 실패';
const prev = $('Build Gemini Request').first().json;

return [{
  json: {
    slackPayload: {
      text: '📊 *POCAT 일일 비즈니스 인사이트 — ' + prev.reportDate + '*',
      attachments: [{
        color: '#36a64f',
        text: report,
        footer: 'POCAT Business Intelligence | Powered by Gemini',
        ts: Math.floor(Date.now() / 1000)
      }]
    }
  }
}];
